//! Generated data tables and enums for the jackdaw engine.
//!
//! The tables (centers, blinds, tags, stakes, seals, playing cards, poker hands, challenges,
//! blind amounts) are generated by `cargo xtask codegen` from `jackdaw/engine/data/*.json`, which
//! is extracted from the game's Lua source, and the output is checked in; CI runs
//! `cargo xtask codegen --check` to keep it in sync. Like `jackdaw-core`, this crate has no PyO3
//! dependency and no global mutable state.
#![forbid(unsafe_code)]

mod generated;
mod types;

pub use generated::*;
pub use types::*;

/// The Balatro release the tables are extracted from (`version.jkr` of the game source).
pub const BALATRO_VERSION: &str = "1.0.1o-FULL";

/// The center with key `key` (`G.P_CENTERS[key]`).
pub fn center_by_key(key: &str) -> Option<CenterId> {
    CENTER_KEYS
        .binary_search_by(|(k, _)| (*k).cmp(key))
        .ok()
        .map(|i| CENTER_KEYS[i].1)
}

/// The blind with key `key` (`G.P_BLINDS[key]`).
pub fn blind_by_key(key: &str) -> Option<BlindId> {
    BLINDS
        .iter()
        .position(|b| b.key == key)
        .map(|i| BlindId(i as u8))
}

/// The tag with key `key` (`G.P_TAGS[key]`).
pub fn tag_by_key(key: &str) -> Option<TagId> {
    TAGS.iter()
        .position(|t| t.key == key)
        .map(|i| TagId(i as u8))
}

/// The playing-card front with key `key` (`G.P_CARDS[key]`, e.g. `"H_A"`).
pub fn card_by_key(key: &str) -> Option<CardId> {
    P_CARDS
        .binary_search_by(|c| c.key.cmp(key))
        .ok()
        .map(|i| CardId(i as u8))
}

/// `G.P_CARDS[suit .. '_' .. rank]` without building the key (`suit` and `rank` are the
/// one-letter codes, e.g. `"H"` and `"A"`).
pub fn card_by_parts(suit: &str, rank: &str) -> Option<CardId> {
    P_CARDS
        .binary_search_by(|c| {
            let (s, r) = c.key.split_once('_').expect("a playing-card key");
            s.cmp(suit).then_with(|| r.cmp(rank))
        })
        .ok()
        .map(|i| CardId(i as u8))
}

/// The centers named like `id`, `id` included: `Card:set_ability` marks every one of them in
/// `G.GAME.used_jokers` (card.lua:349-354).
pub fn same_name_centers(id: CenterId) -> &'static [CenterId] {
    static GROUPS: std::sync::OnceLock<Vec<Vec<CenterId>>> = std::sync::OnceLock::new();
    let groups = GROUPS.get_or_init(|| {
        CENTERS
            .iter()
            .map(|c| {
                (0..CENTERS.len())
                    .filter(|&i| CENTERS[i].name == c.name)
                    .map(|i| CenterId(i as u16))
                    .collect()
            })
            .collect()
    });
    &groups[usize::from(id.0)]
}

/// The challenge with id `id`.
pub fn challenge_by_id(id: &str) -> Option<&'static Challenge> {
    CHALLENGES.iter().find(|c| c.id == id)
}

/// `get_blind_amount(ante)` at `G.GAME.modifiers.scaling` 1, 2 or 3, as LuaJIT computes it.
pub fn blind_amount(scaling: u8, ante: i64) -> f64 {
    let row = &BLIND_AMOUNT_BITS[(scaling.clamp(1, 3) - 1) as usize];
    // Antes below 1 are all 100; past the table the endless formula stays NaN.
    let index = (ante + 1).clamp(0, row.len() as i64 - 1) as usize;
    f64::from_bits(row[index])
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn targets_balatro_1_0_1o() {
        assert!(BALATRO_VERSION.starts_with("1.0.1o"));
    }

    #[test]
    fn centers_are_grouped_by_set_in_lua_order() {
        assert_eq!(CENTERS.len(), 299);
        assert_eq!(centers::J_JOKER, CenterId(0));
        assert_eq!(center_by_key("j_joker"), Some(centers::J_JOKER));
        assert_eq!(center_by_key("nope"), None);
        let jokers: Vec<_> = CENTERS.iter().take(150).collect();
        assert!(jokers.iter().all(|c| c.set == CenterSet::Joker));
        assert!(jokers.windows(2).all(|w| w[0].order < w[1].order));
        assert_eq!(POOL_JOKER.len(), 150);
        assert_eq!(POOL_TAROT.len(), 22);
        assert_eq!(POOL_PLANET.len(), 12);
        assert_eq!(POOL_SPECTRAL.len(), 18);
        assert_eq!(POOL_VOUCHER.len(), 32);
        assert_eq!(POOL_BOOSTER.len(), 32);
        assert_eq!(POOL_ENHANCED.len(), 8);
        assert_eq!(
            JOKER_RARITY_POOLS.iter().map(|p| p.len()).sum::<usize>(),
            150
        );
        // b_challenge is omitted from the Back pool.
        assert!(!POOL_BACK.iter().any(|c| c.key() == "b_challenge"));
    }

    #[test]
    fn center_fields() {
        let castle = center_by_key("j_castle").unwrap().get();
        assert_eq!(castle.name, "Castle");
        assert_eq!(castle.rarity, Some(2));
        assert!(!castle.perishable_compat);
        let extra = castle.config("extra").unwrap();
        assert_eq!(extra.get("chip_mod").and_then(Value::as_num), Some(3.0));
        let magician = center_by_key("c_magician").unwrap().get();
        assert_eq!(
            magician.config("mod_conv").and_then(Value::as_str),
            Some("m_lucky")
        );
        assert_eq!(magician.config_num("max_highlighted"), Some(2.0));
        assert_eq!(
            center_by_key("v_retcon").unwrap().get().requires,
            &["v_directors_cut"]
        );
    }

    #[test]
    fn other_tables() {
        assert_eq!(BLINDS.len(), 30);
        assert_eq!(blinds::BL_SMALL.key(), "bl_small");
        assert_eq!(TAGS.len(), 24);
        assert_eq!(STAKES.len(), 8);
        assert_eq!(STAKES[7].key, "stake_gold");
        assert_eq!(P_CARDS.len(), 52);
        assert_eq!(P_CARDS[0].key, "C_2");
        assert_eq!(
            card_by_key("H_A").map(|c| c.get().name),
            Some("Ace of Hearts")
        );
        assert_eq!(HANDS[0].name, "Flush Five");
        assert_eq!(HANDS[11].name, "High Card");
        assert_eq!(CHALLENGES.len(), 20);
        assert_eq!(
            challenge_by_id("c_omelette_1").unwrap().name,
            "The Omelette"
        );
    }

    #[test]
    fn blind_amounts() {
        assert_eq!(blind_amount(1, 0), 100.0);
        assert_eq!(blind_amount(1, 1), 300.0);
        assert_eq!(blind_amount(1, 8), 50_000.0);
        assert_eq!(blind_amount(2, 8), 100_000.0);
        assert_eq!(blind_amount(3, 8), 200_000.0);
        assert_eq!(blind_amount(1, 9), 110_000.0);
        assert!(blind_amount(1, 39).is_nan());
        assert!(blind_amount(1, 1000).is_nan());
    }
}
